def _require_roles() -> None:
    """Fail loudly if provisioning skipped backend/db/init/00-init-app-role.sql."""
    op.execute(
        """
        DO $$
        BEGIN
            IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'fnh_app') THEN
                RAISE EXCEPTION 'role fnh_app missing: run db/init/00-init-app-role.sql';
            END IF;
            IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'fnh_resolver') THEN
                RAISE EXCEPTION 'role fnh_resolver missing: run db/init/00-init-app-role.sql';
            END IF;
        END
        $$;
        """
    )


def _enable_household_rls() -> None:
    """ADR-0003: ENABLE + FORCE RLS on every household table, keyed on app_household_id().

    app_household_id() maps both an unset GUC (NULL) and a reset one ('') to NULL, so the
    policy fails closed with zero rows instead of erroring on ''::uuid.
    """
    op.execute(
        """
        CREATE FUNCTION app_household_id() RETURNS uuid
        LANGUAGE sql STABLE PARALLEL SAFE
        SET search_path = pg_catalog
        AS $$ SELECT NULLIF(current_setting('app.household_id', true), '')::uuid $$
        """
    )
    scoped = [("households", "id"), *[(t, "household_id") for t in HOUSEHOLD_SCOPED]]
    for table, column in scoped:
        op.execute(f"ALTER TABLE {table} ENABLE ROW LEVEL SECURITY")
        op.execute(f"ALTER TABLE {table} FORCE ROW LEVEL SECURITY")
        op.execute(
            f"CREATE POLICY household_isolation ON {table} "
            f"USING ({column} = app_household_id()) "
            f"WITH CHECK ({column} = app_household_id())"
        )
    for table, columns in RESOLVER_COLUMNS.items():
        op.execute(f"GRANT SELECT ({', '.join(columns)}) ON {table} TO fnh_resolver")
        op.execute(
            f"CREATE POLICY resolver_lookup ON {table} FOR SELECT TO fnh_resolver USING (true)"
        )


def _create_resolver_functions() -> None:
    """ADR-0009: the whole pre-auth surface. Ids only, live credentials only."""
    op.execute(
        """
        CREATE FUNCTION auth_resolve_device(p_token_hash text)
        RETURNS TABLE (device_id uuid, household_id uuid)
        LANGUAGE sql STABLE SECURITY DEFINER
        SET search_path = pg_catalog, public
        AS $$
            SELECT d.id, d.household_id FROM public.devices d
            WHERE d.token_hash = p_token_hash AND d.revoked_at IS NULL
        $$
        """
    )
    op.execute(
        """
        CREATE FUNCTION auth_resolve_magic_link(p_token_hash text)
        RETURNS TABLE (magic_link_id uuid, account_id uuid, household_id uuid)
        LANGUAGE sql STABLE SECURITY DEFINER
        SET search_path = pg_catalog, public
        AS $$
            SELECT m.id, m.account_id, m.household_id
            FROM public.magic_links m
            JOIN public.accounts a ON a.id = m.account_id AND a.household_id = m.household_id
            WHERE m.token_hash = p_token_hash
              AND m.used_at IS NULL
              AND m.expires_at > now()
              AND a.disabled_at IS NULL
        $$
        """
    )
    op.execute(
        """
        CREATE FUNCTION auth_resolve_account_by_email(p_email text)
        RETURNS TABLE (account_id uuid, household_id uuid)
        LANGUAGE sql STABLE SECURITY DEFINER
        SET search_path = pg_catalog, public
        AS $$
            SELECT a.id, a.household_id FROM public.accounts a
            WHERE lower(a.email) = lower(p_email) AND a.disabled_at IS NULL
        $$
        """
    )
    op.execute(
        """
        CREATE FUNCTION auth_resolve_household_by_slug(p_slug text)
        RETURNS uuid
        LANGUAGE sql STABLE SECURITY DEFINER
        SET search_path = pg_catalog, public
        AS $$ SELECT h.id FROM public.households h WHERE h.join_slug = p_slug $$
        """
    )
    op.execute(
        """
        CREATE FUNCTION worker_list_household_ids()
        RETURNS SETOF uuid
        LANGUAGE sql STABLE SECURITY DEFINER
        SET search_path = pg_catalog, public
        AS $$ SELECT h.id FROM public.households h ORDER BY h.id $$
        """
    )
    for fn in RESOLVER_FUNCTIONS:
        op.execute(f"ALTER FUNCTION {fn} OWNER TO fnh_resolver")
        op.execute(f"REVOKE ALL ON FUNCTION {fn} FROM PUBLIC")
        op.execute(f"GRANT EXECUTE ON FUNCTION {fn} TO fnh_app")
